/// The constant's name, from `SECOND_OF_DAY` or `ChronoField.SECOND_OF_DAY`.
fn constant_name<'t>(context: &'t Context, argument: Node) -> Option<&'t str> {
    match argument.kind() {
        "identifier" => Some(context.text(argument)),
        "field_access" => argument.child_by_field_name("field").map(|field| context.text(field)),
        _ => None,
    }
}

pub fn temporal_accessor_get_chrono_field(context: &Context, call: Node) {
    if call.kind() != "method_invocation" {
        return;
    }
    let name = call.child_by_field_name("name").map_or("", |name| context.text(name));
    if name != "get" && name != "getLong" {
        return;
    }
    let list = arguments(call);
    let [argument] = list.as_slice() else { return };
    let Some(field) = constant_name(context, *argument) else { return };
    let Some(resolved) = context.resolver.resolve_call(call) else { return };
    if resolved.method.parameters != [Type::class("java.time.temporal.TemporalField")] {
        return;
    }
    let Some((_, fields)) = UNSUPPORTED.iter().find(|(owner, _)| *owner == resolved.declaring) else { return };
    if fields.split(' ').any(|unsupported| unsupported == field) {
        let message = "TemporalAccessor.get() only works for certain values of ChronoField.";
        context.report_fixed("TemporalAccessorGetChronoField", call, preferred(context, call), message, &[]);
    }
}
